const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
(async()=>{let lib;for(const entry of process.env.PATH.split(path.delimiter)){const p=path.resolve(entry,'../firebase-tools/lib');if(fs.existsSync(path.join(p,'requireAuth.js'))){lib=p;break}}
assert.ok(lib);const account='phuckk2101@gmail.com',options={project:'bepxinh-b0be7',account,nonInteractive:true};const auth=require(path.join(lib,'auth'));auth.setActiveAccount(options,auth.selectAccount(account,process.cwd()));assert.equal(options.user.email,account);await require(path.join(lib,'requireAuth')).requireAuth(options);const {Client}=require(path.join(lib,'apiv2'));const result=(await new Client({urlPrefix:'https://cloudbilling.googleapis.com',auth:true}).get('/v1/projects/bepxinh-b0be7/billingInfo')).body;console.log(JSON.stringify({project:options.project,billingEnabled:result.billingEnabled===true}));})().catch(e=>{console.error('Billing check failed:',e.status || e.code || 'unknown');process.exitCode=1});
